// Bubble Map — Geo, route: jsx
// Source: bubble-map_2
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { FeatureCollection, MultiLineString } from 'geojson';
import statesTopology from 'us-atlas/states-10m.json';
import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from bubbleMap ----
const topology = statesTopology as unknown as Topology;
const statesObject = topology.objects.states as GeometryCollection;

const usStates = feature(topology, statesObject) as FeatureCollection;
const usNation = feature(topology, topology.objects.nation as GeometryCollection) as FeatureCollection;
/** Internal borders only, so the coastline is not double-stroked. */
const usStateBorders = mesh(topology, statesObject, (a, b) => a !== b) as MultiLineString;

// Stand-in for a per-state population statistic: an FNV-1a hash of the state's FIPS id,
// avalanche-mixed then mapped exponentially so the spread matches real state populations.
function stateValue(id: string): number {
  let hash = 2166136261;
  for (let index = 0; index < id.length; index++) {
    hash ^= id.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  hash ^= hash >>> 15;
  hash = Math.imul(hash, 2246822507);
  hash ^= hash >>> 13;
  return Math.round(600000 * Math.exp(((hash >>> 0) / 4294967296) * 4.2));
}

const MARGIN = { top: 8, right: 8, bottom: 8, left: 8 };

/** One value per state FIPS id, encoded as the area of a circle on that state's centroid. */
export type Data = Record<string, number>;

const DEMO: Data = Object.fromEntries(
  usStates.features.map((state) => [String(state.id), stateValue(String(state.id))])
);

const formatValue = d3.format(',.0f');

export default function BubbleMap({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const path = useMemo(() => {
    const projection = d3.geoAlbersUsa().fitSize([innerWidth, innerHeight], usNation);
    return d3.geoPath(projection);
  }, [innerWidth, innerHeight]);

  // Descending, so the largest circles are drawn first and never hide the small ones.
  const bubbles = useMemo(
    () =>
      usStates.features
        .map((state) => {
          const id = String(state.id);
          const [cx, cy] = path.centroid(state);
          return {
            id,
            name: String(state.properties?.name ?? id),
            value: data[id],
            cx,
            cy
          };
        })
        .filter((d) => Number.isFinite(d.cx) && Number.isFinite(d.cy))
        .sort((a, b) => d3.descending(a.value, b.value)),
    [data, path]
  );

  const radius = useMemo(
    () =>
      d3
        .scaleSqrt()
        .domain([0, d3.max(bubbles, (d) => d.value) ?? 0])
        .range([0, Math.max(4, innerWidth / 22)]),
    [bubbles, innerWidth]
  );

  const legendValues = useMemo(() => radius.ticks(4).slice(1), [radius]);

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Bubble map of estimated population by US state">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <path d={path(usNation) ?? undefined} fill="var(--line)" />
        <path
          d={path(usStateBorders) ?? undefined}
          fill="none"
          stroke="var(--bg)"
          strokeLinejoin="round"
        />
        <g fill="var(--accent)" fillOpacity={0.55} stroke="var(--bg)" strokeWidth={0.5}>
          {bubbles.map((d) => (
            <circle key={d.id} cx={d.cx} cy={d.cy} r={radius(d.value)}>
              <title>{`${d.name}\n${formatValue(d.value)}`}</title>
            </circle>
          ))}
        </g>
        <g
          transform={`translate(${innerWidth - radius.range()[1] - 8},${innerHeight - 6})`}
          fill="var(--muted)"
          textAnchor="middle"
          fontSize={10}
        >
          {legendValues.map((value) => (
            <g key={value}>
              <circle cy={-radius(value)} r={radius(value)} fill="none" stroke="var(--muted)" />
              <text y={-2 * radius(value)} dy="1.3em">
                {radius.tickFormat(4, 's')(value)}
              </text>
            </g>
          ))}
        </g>
      </g>
    </svg>
  );
}
